rv = sConnection->ExecuteSimpleSQL(
    "CREATE INDEX messages_flags ON messages(flags);"_ns);
NS_ENSURE_SUCCESS(rv, rv);
rv = sConnection->ExecuteSimpleSQL(
    "CREATE TABLE message_properties ( \
      id INTEGER REFERENCES messages(id), \
      name TEXT, \
      value ANY, \
      PRIMARY KEY(id, name) \
    );"_ns);
NS_ENSURE_SUCCESS(rv, rv);
